ALTER TABLE public.bank_transactions ADD COLUMN confirmation_status text NOT NULL DEFAULT 'unclaimed', ADD COLUMN confirmed_by uuid, ADD COLUMN confirmed_at timestamptz;
UPDATE public.bank_transactions SET confirmation_status='confirmed',confirmed_by=coalesce(claimed_by,reconciled_by),confirmed_at=coalesce(claimed_at,reconciled_at) WHERE status='reconciled' OR (status='pending_reconciliation' AND claimed_by IS NOT NULL AND claimed_at IS NOT NULL AND money_type IN ('deposit','payment','extra_payment','refund','other') AND btrim(coalesce(note,''))<>'' AND (money_type='other' OR btrim(coalesce(customer,''))<>''));
ALTER TABLE public.bank_transactions ADD CONSTRAINT bank_tx_confirmation_status_check CHECK (confirmation_status IN ('unclaimed','confirmed'));
COMMENT ON COLUMN public.bank_transactions.status IS 'DEPRECATED: legacy workflow compatibility and historical reconciliation; confirmation_status is authoritative.';
COMMENT ON COLUMN public.bank_transactions.reconciled_by IS 'Historical accounting actor retained; new confirmations use confirmed_by.';
COMMENT ON COLUMN public.bank_transactions.reconciled_at IS 'Historical reconciliation time retained; new confirmations use confirmed_at.';
CREATE OR REPLACE FUNCTION private.fin_can_see(_uid uuid,_tx uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT _uid IS NOT NULL AND private.is_active(_uid) AND EXISTS(SELECT 1 FROM public.bank_transactions t LEFT JOIN public.bank_accounts a ON a.id=t.bank_account_id WHERE t.id=_tx AND CASE WHEN t.operation_test THEN private.fin_super(_uid) ELSE (private.sig_can(_uid,'finance.incoming.manage') OR private.sig_can(_uid,'finance.incoming.reconcile') OR (t.source<>'bank' AND private.sig_can(_uid,'finance.incoming.manual_manage')) OR (CASE WHEN t.source='bank' THEN (private.sig_can(_uid,'finance.incoming.view') OR private.sig_can(_uid,'finance.incoming.claim')) AND coalesce(a.share_sale,false) ELSE private.sig_can(_uid,'finance.incoming.manual_view') END AND (t.claimed_by=_uid OR (t.claimed_by IS NULL AND t.confirmation_status='unclaimed'))) OR (t.source<>'bank' AND t.created_by=_uid AND private.sig_can(_uid,'finance.incoming.manual_create') AND t.claimed_by IS NULL AND t.confirmation_status='unclaimed')) END); $$;
CREATE OR REPLACE FUNCTION private.fin_snap(t public.bank_transactions) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS $$ SELECT jsonb_build_object('status',t.status,'confirmation_status',t.confirmation_status,'confirmed_by',t.confirmed_by,'confirmed_at',t.confirmed_at,'customer',t.customer,'money_type',t.money_type,'ref_code',t.ref_code,'note',t.note,'claimed_by',t.claimed_by,'claimed_at',t.claimed_at,'reconciled_by',t.reconciled_by,'reconciled_at',t.reconciled_at,'info_reason',t.info_reason,'amount',t.amount,'source',t.source,'received_date',t.received_date,'description',t.description,'cancelled',t.cancelled_at IS NOT NULL); $$;
CREATE OR REPLACE FUNCTION public.fin_claim(_tx uuid,_customer text,_type text,_ref text,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE t public.bank_transactions; me uuid:=auth.uid(); n int; BEGIN
IF NOT coalesce(private.sig_can(me,'finance.incoming.claim'),false) THEN RAISE EXCEPTION 'Bạn không có quyền xác nhận giao dịch'; END IF;
PERFORM private.fin_check(_customer,_type,_note);
SELECT * INTO t FROM public.bank_transactions WHERE id=_tx FOR UPDATE;
IF NOT FOUND OR NOT private.fin_can_see(me,_tx) THEN RAISE EXCEPTION 'Không tìm thấy giao dịch hoặc giao dịch đã được người khác nhận'; END IF;
IF t.operation_test OR t.cancelled_at IS NOT NULL THEN RAISE EXCEPTION 'Không thể xử lý giao dịch lưu trữ hoặc đã hủy'; END IF;
IF t.confirmation_status<>'unclaimed' OR t.claimed_by IS NOT NULL THEN RAISE EXCEPTION 'Giao dịch đã được xác nhận, vui lòng tải lại'; END IF;
UPDATE public.bank_transactions SET customer=btrim(_customer),money_type=_type,ref_code=nullif(btrim(coalesce(_ref,'')),''),note=btrim(_note),claimed_by=me,claimed_at=now(),confirmed_by=me,confirmed_at=now(),confirmation_status='confirmed',status='pending_reconciliation',info_reason=NULL WHERE id=_tx AND claimed_by IS NULL AND confirmation_status='unclaimed';
GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Giao dịch đã được người khác nhận'; END IF;
INSERT INTO public.bank_transaction_events(tx_id,actor_id,action,before,after) SELECT _tx,me,'claim',private.fin_snap(t),private.fin_snap(x) FROM public.bank_transactions x WHERE x.id=_tx;
END; $$;
CREATE OR REPLACE FUNCTION public.fin_reconcile(_tx uuid,_customer text DEFAULT NULL,_type text DEFAULT NULL,_ref text DEFAULT NULL,_note text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE t public.bank_transactions; me uuid:=auth.uid(); BEGIN
IF NOT coalesce(private.sig_can(me,'finance.incoming.reconcile'),false) THEN RAISE EXCEPTION 'Bạn không có quyền xác nhận khoản loại Khác'; END IF;
SELECT * INTO t FROM public.bank_transactions WHERE id=_tx FOR UPDATE;
IF NOT FOUND OR NOT private.fin_can_see(me,_tx) THEN RAISE EXCEPTION 'Không tìm thấy giao dịch'; END IF;
IF t.operation_test OR t.cancelled_at IS NOT NULL THEN RAISE EXCEPTION 'Không thể xử lý giao dịch lưu trữ hoặc đã hủy'; END IF;
IF t.confirmation_status<>'unclaimed' OR t.claimed_by IS NOT NULL THEN RAISE EXCEPTION 'Giao dịch đã được người khác xử lý, vui lòng tải lại'; END IF;
IF _type IS DISTINCT FROM 'other' OR _customer IS NOT NULL THEN RAISE EXCEPTION 'Không còn bước đối soát; chỉ được xác nhận trực tiếp khoản loại Khác'; END IF;
PERFORM private.fin_check(NULL,'other',_note);
UPDATE public.bank_transactions SET money_type='other',note=btrim(_note),confirmation_status='confirmed',confirmed_by=me,confirmed_at=now(),status='reconciled',info_reason=NULL WHERE id=_tx;
INSERT INTO public.bank_transaction_events(tx_id,actor_id,action,before,after) SELECT _tx,me,'confirm_other',private.fin_snap(t),private.fin_snap(x) FROM public.bank_transactions x WHERE x.id=_tx;
END; $$;
CREATE OR REPLACE FUNCTION public.fin_request_info(_tx uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN RAISE EXCEPTION 'Bước yêu cầu đối soát đã ngừng sử dụng; hãy điều chỉnh ghi chú theo quyền'; END; $$;
CREATE OR REPLACE FUNCTION public.fin_note_update(_tx uuid,_note text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE t public.bank_transactions; me uuid:=auth.uid(); BEGIN
SELECT * INTO t FROM public.bank_transactions WHERE id=_tx FOR UPDATE;
IF NOT FOUND OR NOT private.fin_can_see(me,_tx) THEN RAISE EXCEPTION 'Không tìm thấy giao dịch'; END IF;
IF NOT (coalesce(private.sig_can(me,'finance.incoming.reconcile'),false) OR coalesce(private.sig_can(me,'finance.incoming.manage'),false) OR (t.claimed_by=me AND coalesce(private.sig_can(me,'finance.incoming.claim'),false))) THEN RAISE EXCEPTION 'Bạn không có quyền điều chỉnh ghi chú'; END IF;
IF t.operation_test OR t.cancelled_at IS NOT NULL THEN RAISE EXCEPTION 'Không thể sửa giao dịch lưu trữ hoặc đã hủy'; END IF;
IF coalesce(btrim(_note),'')='' OR length(_note)>2000 THEN RAISE EXCEPTION 'Ghi chú phải có từ 1 đến 2000 ký tự'; END IF;
IF coalesce(btrim(_reason),'')='' OR length(_reason)>2000 THEN RAISE EXCEPTION 'Vui lòng nhập lý do điều chỉnh (tối đa 2000 ký tự)'; END IF;
UPDATE public.bank_transactions SET note=btrim(_note) WHERE id=_tx;
INSERT INTO public.bank_transaction_events(tx_id,actor_id,action,before,after,reason) SELECT _tx,me,'note_edit',private.fin_snap(t),private.fin_snap(x),btrim(_reason) FROM public.bank_transactions x WHERE x.id=_tx;
END; $$;
REVOKE ALL ON FUNCTION public.fin_note_update(uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fin_note_update(uuid,text,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION private.fin_confirmation_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$ BEGIN
IF TG_OP='UPDATE' AND OLD.operation_test AND (NEW.confirmation_status,NEW.confirmed_by,NEW.confirmed_at) IS DISTINCT FROM (OLD.confirmation_status,OLD.confirmed_by,OLD.confirmed_at) THEN RAISE EXCEPTION 'Giao dịch thuộc lịch sử kiểm thử chỉ được xem, không xử lý'; END IF;
IF TG_OP='UPDATE' AND NEW.status='unclaimed' AND OLD.status<>'unclaimed' THEN NEW.confirmation_status:='unclaimed'; NEW.confirmed_by:=NULL; NEW.confirmed_at:=NULL; END IF;
IF TG_OP='UPDATE' AND OLD.confirmation_status='confirmed' AND (NEW.source,NEW.amount,NEW.received_date,NEW.description,NEW.cancelled_at) IS DISTINCT FROM (OLD.source,OLD.amount,OLD.received_date,OLD.description,OLD.cancelled_at) THEN
IF NOT coalesce(private.sig_can(auth.uid(),'finance.incoming.manage'),false) THEN RAISE EXCEPTION 'Khoản đã xác nhận chỉ người quản lý được sửa hoặc hủy'; END IF;
IF NEW.cancelled_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.bank_transaction_events e WHERE e.tx_id=OLD.id AND e.created_at=now() AND e.action='manual_edit') THEN NULL; END IF;
END IF;
RETURN NEW; END; $$;
CREATE TRIGGER fin_confirmation_guard BEFORE INSERT OR UPDATE ON public.bank_transactions FOR EACH ROW EXECUTE FUNCTION private.fin_confirmation_guard();
CREATE OR REPLACE FUNCTION public.fin_incoming_stats(_src text DEFAULT NULL,_acc uuid DEFAULT NULL,_from timestamptz DEFAULT NULL,_to timestamptz DEFAULT NULL,_q text DEFAULT NULL,_sale uuid DEFAULT NULL) RETURNS TABLE(status text,source text,n bigint,total numeric) LANGUAGE sql STABLE SET search_path=pg_catalog,public AS $$ WITH search AS(SELECT CASE WHEN btrim(coalesce(_q,'')) ~ '^[0-9]+([.,][0-9]{3})*$' AND length(replace(replace(btrim(_q),'.',''),',',''))<=16 THEN replace(replace(btrim(_q),'.',''),',','')::numeric END amount,btrim(coalesce(_q,'')) text,public.fin_can_view_totals() totals) SELECT t.confirmation_status,CASE WHEN t.source='bank' THEN 'bank' ELSE 'manual' END,count(*),coalesce(sum(t.amount) FILTER(WHERE s.totals OR t.claimed_by=auth.uid()),0) FROM public.bank_transactions t CROSS JOIN search s WHERE NOT t.operation_test AND t.cancelled_at IS NULL AND t.amount>0 AND (_src IS NULL OR t.source=_src) AND (_acc IS NULL OR t.bank_account_id=_acc) AND (_from IS NULL OR t.transaction_at>=_from) AND (_to IS NULL OR t.transaction_at<_to) AND (_sale IS NULL OR t.claimed_by=_sale) AND (s.text='' OR CASE WHEN s.amount IS NOT NULL THEN t.amount=s.amount ELSE t.description ILIKE '%'||s.text||'%' OR t.reference_number ILIKE '%'||s.text||'%' OR t.note ILIKE '%'||s.text||'%' OR t.customer ILIKE '%'||s.text||'%' END) GROUP BY 1,2; $$;
CREATE OR REPLACE FUNCTION public.fin_incoming_history_stats(_src text DEFAULT NULL,_acc uuid DEFAULT NULL,_from timestamptz DEFAULT NULL,_to timestamptz DEFAULT NULL,_q text DEFAULT NULL,_sale uuid DEFAULT NULL) RETURNS TABLE(status text,source text,n bigint,total numeric) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT private.fin_super(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được xem lịch sử kiểm thử'; END IF; RETURN QUERY WITH search AS(SELECT CASE WHEN btrim(coalesce(_q,'')) ~ '^[0-9]+([.,][0-9]{3})*$' AND length(replace(replace(btrim(_q),'.',''),',',''))<=16 THEN replace(replace(btrim(_q),'.',''),',','')::numeric END amount,btrim(coalesce(_q,'')) text) SELECT t.confirmation_status,CASE WHEN t.source='bank' THEN 'bank' ELSE 'manual' END,count(*),coalesce(sum(t.amount),0) FROM public.bank_transactions t CROSS JOIN search s WHERE t.operation_test AND t.cancelled_at IS NULL AND t.amount>0 AND (_src IS NULL OR t.source=_src) AND (_acc IS NULL OR t.bank_account_id=_acc) AND (_from IS NULL OR t.transaction_at>=_from) AND (_to IS NULL OR t.transaction_at<_to) AND (_sale IS NULL OR t.claimed_by=_sale) AND (s.text='' OR CASE WHEN s.amount IS NOT NULL THEN t.amount=s.amount ELSE t.description ILIKE '%'||s.text||'%' OR t.reference_number ILIKE '%'||s.text||'%' OR t.note ILIKE '%'||s.text||'%' OR t.customer ILIKE '%'||s.text||'%' END) GROUP BY 1,2; END; $$;